import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';

// Generated by tool/make_sounds.py.
const sources = {
  tap: require('../assets/sounds/tap.wav'),
  open: require('../assets/sounds/open.wav'),
  close: require('../assets/sounds/close.wav'),
  save: require('../assets/sounds/save.wav'),
  countdown: require('../assets/sounds/countdown.wav'),
  go: require('../assets/sounds/go.wav'),
  correct: require('../assets/sounds/correct.wav'),
  pass: require('../assets/sounds/pass.wav'),
  tick: require('../assets/sounds/tick.wav'),
  timesup: require('../assets/sounds/timesup.wav'),
  fanfare: require('../assets/sounds/fanfare.wav'),
};

export type SoundName = keyof typeof sources;

const players = new Map<SoundName, AudioPlayer>();
let enabled = true;
let ready = false;

/** Loads every sound once at startup. Safe to call more than once. */
export function initSounds(): void {
  if (ready) return;
  ready = true;
  // A party game should be heard even with the ringer switch on silent;
  // the in-app Sound toggle turns it off. Mix with any music playing.
  setAudioModeAsync({ playsInSilentMode: true, interruptionMode: 'mixWithOthers' }).catch(
    () => {},
  );
  for (const [name, source] of Object.entries(sources) as [SoundName, number][]) {
    try {
      players.set(name, createAudioPlayer(source));
    } catch {
      // Audio unavailable (e.g. some test environments): stay silent.
    }
  }
}

export function setSoundEnabled(on: boolean): void {
  enabled = on;
}

/** Plays a sound from the start, cutting off the same sound if still playing. */
export function play(name: SoundName): void {
  if (!enabled) return;
  const player = players.get(name);
  if (!player) return;
  try {
    player.seekTo(0).catch(() => {});
    player.play();
  } catch {
    // Never let a sound failure interrupt the game.
  }
}
